<?php
namespace App\Filament\Resources;
use App\Filament\Resources\StudentAchievementResource\Pages;use App\Models\StudentAchievement;use Illuminate\Support\Facades\DB;
use Filament\Forms;use Filament\Resources\Form;use Filament\Resources\Resource;use Filament\Resources\Table;use Filament\Tables;
class StudentAchievementResource extends Resource{protected static ?string $model=StudentAchievement::class;protected static ?string $modelLabel='достижение';protected static ?string $pluralModelLabel='Достижения';public static function form(Form $form):Form{return $form->schema([Forms\Components\Select::make('student_id')->label('Студент')->options(fn()=>DB::table('students')->where('status','active')->orderBy('last_name')->get()->mapWithKeys(fn($s)=>[$s->id=>$s->last_name.' '.$s->first_name]))->searchable()->required(),Forms\Components\TextInput::make('category')->label('Категория')->required(),Forms\Components\TextInput::make('title')->label('Достижение')->required(),Forms\Components\TextInput::make('level')->label('Уровень'),Forms\Components\TextInput::make('result')->label('Результат'),Forms\Components\DatePicker::make('achieved_on')->label('Дата'),Forms\Components\Textarea::make('note')->label('Примечание')->columnSpan('full')])->columns(2);}public static function table(Table $table):Table{return $table->columns([Tables\Columns\TextColumn::make('achieved_on')->label('Дата')->date('d.m.Y')->sortable(),Tables\Columns\TextColumn::make('student_id')->label('Студент')->formatStateUsing(fn($state)=>($s=DB::table('students')->where('id',$state)->first()) ? trim($s->last_name.' '.$s->first_name) : '—'),Tables\Columns\TextColumn::make('category')->label('Категория'),Tables\Columns\TextColumn::make('title')->label('Достижение')->searchable(),Tables\Columns\TextColumn::make('result')->label('Результат')])->actions([Tables\Actions\EditAction::make()->label('Изменить'),Tables\Actions\Action::make('archive')->label('В архив')->color('danger')->requiresConfirmation()->action(fn($record)=>$record->update(['archived_at'=>now()]))]);}public static function getEloquentQuery():\Illuminate\Database\Eloquent\Builder{return parent::getEloquentQuery()->whereNull('archived_at');}public static function getPages():array{return['index'=>Pages\ListStudentAchievements::route('/'),'create'=>Pages\CreateStudentAchievement::route('/create'),'edit'=>Pages\EditStudentAchievement::route('/{record}/edit')];}}
